mapper.select:
SELECT s.id, s.title, s.content, s.type, s.resource_id, s.category, s.tags, s.difficulty, s.is_public, s.user_id, u.nick_name AS user_name, u.avatar AS user_avatar, s.like_count, s.favorite_count, s.comment_count, s.view_count, s.status, s.created_at FROM forum_shares s LEFT JOIN sys_user u ON s.user_id = u.user_id
s.status = 0
AND s.category = #{category}
ORDER BY
s.like_count DESC, s.created_at DESC s.created_at DESC s.created_at DESC
LIMIT #{offset}, #{limit}
